steps.script:
SettingsService.set("auto_allocate_wounds", true)
var spots = {"U_CUSTODIAN_GUARD_E": Vector2(40, 52), "U_BATTLEWAGON_A": Vector2(40, 44.5)}
for uid in spots:
	var u = GameState.state["units"][uid]
	var c = Vector2.ZERO
	for m in u["models"]:
		c += Vector2(float(m["position"]["x"]), float(m["position"]["y"]))
	c /= u["models"].size()
	var d = spots[uid] * 40.0 - c
	for m in u["models"]:
		m["position"] = {"x": float(m["position"]["x"]) + d.x, "y": float(m["position"]["y"]) + d.y}
var cg = GameState.state["units"]["U_CUSTODIAN_GUARD_E"]
for i in range(3, cg["models"].size()):
	cg["models"][i]["alive"] = false
	cg["models"][i]["current_wounds"] = 0
GameState.state["players"]["1"]["cp"] = 0
GameState.state["players"]["2"]["cp"] = 0
var ph = PhaseManager.get_current_phase_instance()
ph.game_state_snapshot = GameState.create_snapshot()
SceneRefs.main()._recreate_unit_visuals()
SceneRefs.main().charge_controller._refresh_ui()
return RulesEngine.is_unit_engaged("U_BATTLEWAGON_A", GameState.state)

var cc = tree.root.get_node("Main").charge_controller
var out = []
for i in range(cc.target_list.get_item_count()):
	out.append(str(cc.target_list.get_item_metadata(i)))
return ",".join(out)

var pc = PhaseManager.get_current_phase_instance().pending_charges.get("U_BATTLEWAGON_A", {})
print("[ork11e charge flags] pending charge after roll: ", pc)
return int(pc.get("distance", -1)) == 11 and pc.get("targets", []) == ["U_CUSTODIAN_GUARD_E"]

var f = GameState.get_unit("U_BATTLEWAGON_A").get("flags", {})
print("[ork11e charge flags] Battlewagon flags at the start of P2's turn: ", f)
for k in ["charged_this_turn", "fights_first", "has_fought", "has_been_charged", "heroic_intervention"]:
	if f.has(k):
		return "STALE:" + k
return true

var ph = PhaseManager.get_current_phase_instance()
var sel = ph.sequencer_11e.next_selection(GameState.state)
print("[ork11e charge flags] P2 Fight phase selection: ", sel, " selecting=", ph.current_selecting_player)
return "%s|%d|%d" % [str(sel.get("step", "")), int(sel.get("player", 0)), int(ph.current_selecting_player)]

var r = StratagemManager.can_use_stratagem(1, "faction_ork_war_horde_mow_em_down", "U_BATTLEWAGON_A")
print("[ork11e charge flags] MOW 'EM DOWN in P2's Fight phase: ", r)
return r.get("can_use", true)
